input.content:
:root {
  --bg: #150e18;
  --bg-soft: #211426;
  --panel: rgba(35, 24, 39, .82);
  --panel-deep: #241629;
  --ink: #faf1ed;
  --muted: #c7b0b4;
  --muted-2: #9c8389;
  --rose: #e7a0b5;
  --rose-deep: #c96f8c;
  --gold: #e9c391;
  --gold-deep: #c69a67;
  --green: #a9e0ac;
  --line: rgba(255, 227, 220, .1);
  --line-strong: rgba(255, 227, 220, .2);
  --shadow: 0 28px 76px rgba(0, 0, 0, .48);
  --serif: Georgia, 'Iowan Old Style', 'Times New Roman', serif;
  --sans: 'Segoe UI', system-ui, -apple-system, BlinkMacSystemFont, 'Helvetica Neue', Arial, sans-serif;
}

* { box-sizing: border-box; }
html, body { height: 100%; }
body {
  margin: 0;
  background:
    radial-gradient(1100px 780px at 74% -12%, #3b2237 0%, transparent 58%),
    radial-gradient(900px 720px at -8% 108%, #2c1a31 0%, transparent 62%),
    radial-gradient(600px 500px at 50% 50%, #1d1221 0%, #120c15 78%);
  color: var(--ink);
  font-family: var(--sans);
  font-size: 14px;
  -webkit-font-smoothing: antialiased;
  overflow: hidden;
}
button, input { font: inherit; }
button { color: inherit; border: 0; background: none; cursor: pointer; }
button:focus-visible, input:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 2px;
}
.hidden { display: none !important; }
.sr-only {
  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0;
}

/* ---------- App frame ---------- */
.app {
  height: 100dvh;
  display: flex;
  flex-direction: column;
  position: relative;
}
.app::before {
  content: '';
  position: fixed;
  inset: 0;
  pointer-events: none;
  opacity: .35;
  background-image: radial-gradient(rgba(255, 255, 255, .11) .6px, transparent .7px);
  background-size: 4px 4px;
  mix-blend-mode: soft-light;
  z-index: 1;
}

.topbar {
  height: 66px;
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 24px;
  border-bottom: 1px solid var(--line);
  background: linear-gradient(180deg, rgba(26, 16, 30, .72), rgba(22, 14, 25, .32));
  backdrop-filter: blur(12px);
  position: relative;
  z-index: 4;
}
.brand {
  display: flex;
  align-items: center;
  gap: 12px;
  text-align: left;
  padding: 4px;
  border-radius: 12px;
}
.brand-mark {
  width: 40px;
  height: 40px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  font-family: var(--serif);
  font-size: 22px;
  color: #2b1a1d;
  background: linear-gradient(145deg, #f8e3bd 0%, #e8bf88 42%, #bd8d5d 100%);
  box-shadow: 0 0 0 1px rgba(255, 240, 214, .32), 0 6px 18px rgba(0, 0, 0, .35), inset 0 1px 0 rgba(255, 255, 255, .7);
}
.brand-text { display: flex; flex-direction: column; line-height: 1.1; }
.brand-text b { font-family: var(--serif); font-weight: 500; font-size: 18px; letter-spacing: .015em; }
.brand-text small {
  font-size: 8px;
  text-transform: uppercase;
  letter-spacing: .28em;
  color: var(--muted-2);
  margin-top: 4px;
}
.top-right { display: flex; align-items: center; gap: 8px; }
.hud {
  display: flex;
  align-items: center;
  gap: 9px;
  height: 36px;
  padding: 0 14px;
  margin-right: 6px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: rgba(255, 255, 255, .035);
  font-size: 11px;
  letter-spacing: .06em;
  color: var(--muted);
}
.hud strong { color: var(--gold); font-weight: 600; letter-spacing: .02em; }
.hud-dot { width: 3px; height: 3px; border-radius: 50%; background: var(--muted-2); }
.icon-btn {
  width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 50%;
  color: var(--muted);
  transition: .18s ease;
}
.icon-btn:hover { color: var(--gold); border-color: var(--line-strong); background: rgba(255, 255, 255, .05); }
.icon-btn svg { width: 19px; height: 19px; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
#soundBtn.is-muted .sound-wave { opacity: .18; }

.workspace {
  position: relative;
  z-index: 2;
  min-height: 0;
  flex: 1;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 396px;
  gap: 20px;
  padding: 18px 22px 20px;
}

/* ---------- Stage / mirror ---------- */
.stage-wrap {
  min-height: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
}
.mirror {
  position: relative;
  flex: 1 1 auto;
  min-height: 0;
  aspect-ratio: 900 / 1120;
  border-radius: 999px 999px 28px 28px;
  background: #2a1a24;
  border: 1px solid rgba(233, 195, 145, .58);
  box-shadow:
    0 0 0 6px rgba(233, 195, 145, .055),
    0 0 0 7px rgba(233, 195, 145, .19),
    0 30px 80px rgba(0, 0, 0, .55),
    0 0 90px rgba(201, 111, 140, .1),
    inset 0 0 60px rgba(0, 0, 0, .3);
  overflow: hidden;
  isolation: isolate;
}
.mirror::after {
  content: '';
  position: absolute;
  inset: 0;
  pointer-events: none;
  border-radius: inherit;
  box-shadow: inset 0 0 0 1px rgba(255, 246, 228, .2), inset 0 -30px 70px rgba(25, 12, 22, .28);
}
#faceCanvas {
  display: block;
  width: 100%;
  height: 100%;
  touch-action: none;
  cursor: default;
}
#faceCanvas.can-paint { cursor: crosshair; }
#faceCanvas.can-sticker { cursor: copy; }
.mirror-glass {
  position: absolute;
  inset: 0;
  pointer-events: none;
  border-radius: inherit;
  background:
    linear-gradient(118deg, rgba(255, 255, 255, .17) 0%, rgba(255, 255, 255, .04) 18%, transparent 36%, transparent 70%, rgba(255, 255, 255, .055) 100%),
    radial-gradient(ellipse at 28% 8%, rgba(255, 255, 255, .13), transparent 42%);
  mix-blend-mode: screen;
  opacity: .5;
}
.mirror-caption {
  position: absolute;
  left: 50%;
  bottom: 16px;
  transform: translateX(-50%) translateY(6px);
  padding: 7px 13px;
  border-radius: 999px;
  background: rgba(26, 15, 26, .72);
  border: 1px solid rgba(255, 232, 220, .16);
  backdrop-filter: blur(10px);
  font-size: 10px;
  letter-spacing: .06em;
  color: var(--muted);
  white-space: nowrap;
  opacity: 0;
  pointer-events: none;
  transition: .25s ease;
}
.mirror-caption.is-visible { opacity: 1; transform: translateX(-50%) translateY(0); }

.stage-toolbar {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 6px;
  border: 1px solid var(--line);
  border-radius: 17px;
  background: linear-gradient(180deg, rgba(43, 29, 47, .85), rgba(30, 19, 34, .85));
  box-shadow: 0 12px 30px rgba(0, 0, 0, .26);
  backdrop-filter: blur(12px);
}
.tool-btn {
  height: 40px;
  padding: 0 13px;
  display: flex;
  align-items: center;
  gap: 7px;
  border-radius: 11px;
  color: var(--muted);
  font-size: 11px;
  letter-spacing: .02em;
  transition: .16s ease;
}
.tool-btn:hover:not(:disabled) { background: rgba(255, 255, 255, .06); color: var(--ink); }
.tool-btn:disabled { opacity: .32; cursor: default; }
.tool-btn svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
.present-btn {
  height: 42px;
  padding: 0 20px;
  margin-left: 2px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  border-radius: 12px;
  background: linear-gradient(135deg, #edcda0 0%, #dda9a6 46%, #cf879e 100%);
  color: #29191f;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: .045em;
  box-shadow: 0 7px 22px rgba(201, 111, 140, .25), inset 0 1px 0 rgba(255, 255, 255, .55);
  transition: .18s ease;
  white-space: nowrap;
}
.present-btn:hover { transform: translateY(-1px); filter: brightness(1.04); box-shadow: 0 10px 26px rgba(201, 111, 140, .34), inset 0 1px 0 rgba(255, 255, 255, .55); }
.present-btn:active { transform: translateY(0); }
.present-spark { font-size: 14px; }

/* ---------- Side panel ---------- */
.panel {
  min-height: 0;
  display: flex;
  flex-direction: column;
  border: 1px solid var(--line);
  border-radius: 24px;
  background:
    linear-gradient(170deg, rgba(53, 36, 58, .82) 0%, rgba(33, 21, 38, .9) 42%, rgba(28, 18, 32, .92) 100%);
  box-shadow: var(--shadow);
  backdrop-filter: blur(16px);
  overflow: hidden;
  position: relative;
}
.panel::before {
  content: '';
  position: absolute;
  inset: 0 0 auto;
  height: 120px;
  background: radial-gradient(ellipse at 50% 0%, rgba(231, 160, 181, .12), transparent 72%);
  pointer-events: none;
}
.panel-top { position: relative; padding: 17px 18px 13px; border-bottom: 1px solid var(--line); flex: 0 0 auto; }
.mode-row { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; }
.kicker { display: block; font-size: 8.5px; letter-spacing: .25em; color: var(--gold-deep); text-transform: uppercase; font-weight: 600; }
.mode-row h2 { margin: 5px 0 0; font-family: var(--serif); font-size: 25px; font-weight: 400; letter-spacing: .01em; line-height: 1; }
.round-dots { display: flex; gap: 5px; padding-top: 8px; }
.round-dot { width: 7px; height: 7px; border-radius: 50%; background: rgba(255, 255, 255, .13); transition: .25s ease; }
.round-dot.is-done { background: var(--rose-deep); box-shadow: 0 0 8px rgba(201, 111, 140, .5); }
.round-dot.is-active { background: var(--gold); box-shadow: 0 0 9px rgba(233, 195, 145, .55); }

.free-intro { margin-top: 12px; }
.free-intro p { margin: 0; font-size: 11.5px; line-height: 1.55; color: var(--muted-2); }
.preset-row { display: flex; gap: 6px; flex-wrap: wrap; margin-top: 10px; }
.preset-chip {
  padding: 6px 11px;
  border-radius: 999px;
  border: 1px solid var(--line);
  background: rgba(255, 255, 255, .035);
  font-size: 10px;
  letter-spacing: .04em;
  color: var(--muted);
  transition: .16s ease;
}
.preset-chip:hover { color: var(--gold); border-color: rgba(233, 195, 145, .35); background: rgba(233, 195, 145, .07); }

.client-card {
  margin-top: 12px;
  padding: 12px;
  border-radius: 16px;
  border: 1px solid var(--line);
  background: linear-gradient(145deg, rgba(255, 255, 255, .055), rgba(255, 255, 255, .02));
}
.client-head { display: flex; align-items: center; gap: 9px; }
.avatar {
  width: 40px;
  height: 40px;
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  border-radius: 50%;
  font-family: var(--serif);
  font-size: 18px;
  color: #3a2227;
  background: linear-gradient(145deg, #f2d2c0, #d8a3a6);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, .6), 0 4px 12px rgba(0, 0, 0, .2);
}
.client-id { min-width: 0; flex: 1; }
.client-id h3 { margin: 3px 0 0; font-family: var(--serif); font-size: 17px; font-weight: 400; line-height: 1; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.timer {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 5px 8px;
  border-radius: 999px;
  background: rgba(0, 0, 0, .2);
  border: 1px solid var(--line);
  color: var(--gold);
  font-size: 11px;
  font-variant-numeric: tabular-nums;
  letter-spacing: .04em;
}
.timer svg { width: 12px; height: 12px; fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; }
.timer.is-low { color: #f0a09a; border-color: rgba(240, 160, 154, .3); }
.brief-text { margin: 9px 0 8px; font-size: 11.5px; line-height: 1.5; color: var(--muted); }
.checklist { display: flex; flex-wrap: wrap; gap: 5px; }
.check {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 4px 8px 4px 6px;
  border: 1px solid transparent;
  border-radius: 999px;
  background: rgba(0, 0, 0, .16);
  color: var(--muted-2);
  font-size: 10px;
  line-height: 1.2;
  transition: .2s ease;
}
.check::before { content: '○'; font-size: 9px; opacity: .75; }
.check.is-ok { color: #ddf3dd; border-color: rgba(134, 201, 140, .28); background: rgba(89, 153, 97, .14); }
.check.is-ok::before { content: '✓'; color: var(--green); opacity: 1; }

.tabs {
  flex: 0 0 auto;
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 3px;
  padding: 7px 9px;
  border-bottom: 1px solid var(--line);
  background: rgba(0, 0, 0, .09);
}
.tab {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  padding: 8px 2px 7px;
  border-radius: 11px;
  color: var(--muted-2);
  font-size: 9px;
  letter-spacing: .03em;
  transition: .16s ease;
}
.tab svg { width: 19px; height: 19px; fill: none; stroke: currentColor; stroke-width: 1.45; stroke-linecap: round; stroke-linejoin: round; }
.tab:hover { color: var(--ink); background: rgba(255, 255, 255, .045); }
.tab.is-active { color: var(--gold); background: linear-gradient(180deg, rgba(233, 195, 145, .14), rgba(233, 195, 145, .055)); box-shadow: inset 0 0 0 1px rgba(233, 195, 145, .12); }

.panel-body {
  min-height: 0;
  flex: 1;
  overflow-y: auto;
  padding: 2px 18px 22px;
  scrollbar-width: thin;
  scrollbar-color: rgba(233, 195, 145, .25) transparent;
  overscroll-behavior: contain;
}
.panel-body::-webkit-scrollbar { width: 7px; }
.panel-body::-webkit-scrollbar-thumb { background: rgba(233, 195, 145, .2); border-radius: 99px; }
.tab-pane { display: none; animation: paneIn .22s ease; }
.tab-pane.is-active { display: block; }
@keyframes paneIn { from { opacity: 0; transform: translateY(4px); } to { opacity: 1; transform: none; } }

.group { padding: 14px 0; border-bottom: 1px solid rgba(255, 255, 255, .055); }
.group:last-of-type { border-bottom: 0; }
.group-head { display: flex; align-items: baseline; justify-content: space-between; gap: 10px; margin-bottom: 9px; }
.group-head h4 { margin: 0; font-size: 10.5px; font-weight: 600; letter-spacing: .11em; text-transform: uppercase; color: #e4d3d2; }
.group-head span { font-size: 9.5px; color: var(--muted-2); letter-spacing: .02em; text-align: right; }
.group.split { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }

.swatches { display: flex; flex-wrap: wrap; gap: 8px; }
.swatch {
  position: relative;
  width: 34px;
  height: 34px;
  border-radius: 50%;
  border: 2px solid rgba(255, 255, 255, .1);
  background: var(--c);
  box-shadow: inset 0 1px 1px rgba(255, 255, 255, .32), inset 0 -2px 4px rgba(0, 0, 0, .2), 0 3px 9px rgba(0, 0, 0, .22);
  transition: transform .15s ease, box-shadow .15s ease;
}
.swatch::after {
  content: '';
  position: absolute;
  inset: 4px;
  border-radius: 50%;
  box-shadow: inset 0 1px 2px rgba(255, 255, 255, .18);
  pointer-events: none;
}
.swatch:hover { transform: scale(1.08); }
.swatch.is-active {
  transform: scale(1.07);
  border-color: var(--gold);
  box-shadow: 0 0 0 2px rgba(233, 195, 145, .55), 0 4px 14px rgba(0, 0, 0, .3);
}
.skin-swatches .swatch { width: 38px; height: 38px; }
.shadow-swatches { gap: 7px; }
.shadow-swatches .swatch, .lip-swatches .swatch { width: 31px; height: 31px; }
.swatches.tiny { gap: 7px; margin-top: 10px; }
.swatches.tiny .swatch { width: 24px; height: 24px; }
.brush-swatches .swatch { width: 30px; height: 30px; }
.aura-row { display: flex; gap: 9px; }
.aura-swatch {
  width: 44px;
  height: 34px;
  border-radius: 9px;
  border: 2px solid rgba(255, 255, 255, .12);
  background: var(--c);
  transition: .16s ease;
  position: relative;
  overflow: hidden;
}
.aura-swatch::after { content: ''; position: absolute; inset: 0; background: linear-gradient(180deg, rgba(255,255,255,.25), transparent 60%); }
.aura-swatch:hover { transform: translateY(-2px); }
.aura-swatch.is-active { border-color: var(--gold); box-shadow: 0 0 0 2px rgba(233, 195, 145, .5); }

.slider-row { display: grid; gap: 5px; margin-top: 11px; font-size: 9.5px; color: var(--muted-2); letter-spacing: .03em; }
.mini-control input[type=range] { margin-top: 2px; }
input[type=range] {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 22px;
  background: transparent;
  cursor: pointer;
  margin: 0;
}
input[type=range]::-webkit-slider-runnable-track {
  height: 4px;
  border-radius: 99px;
  background: linear-gradient(90deg, var(--gold) 0 var(--p, 50%), rgba(255, 255, 255, .12) var(--p, 50%) 100%);
}
input[type=range]::-moz-range-track {
  height: 4px;
  border-radius: 99px;
  background: linear-gradient(90deg, var(--gold) 0 var(--p, 50%), rgba(255, 255, 255, .12) var(--p, 50%) 100%);
}
input[type=range]::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: 14px;
  height: 14px;
  margin-top: -5px;
  border-radius: 50%;
  background: #fbf0e7;
  border: 1px solid rgba(80, 48, 40, .3);
  box-shadow: 0 0 0 3px rgba(233, 195, 145, .16), 0 2px 5px rgba(0, 0, 0, .3);
}
input[type=range]::-moz-range-thumb {
  width: 13px;
  height: 13px;
  border-radius: 50%;
  background: #fbf0e7;
  border: 1px solid rgba(80, 48, 40, .3);
  box-shadow: 0 0 0 3px rgba(233, 195, 145, .16);
}

.segmented {
  display: flex;
  gap: 3px;
  padding: 3px;
  margin-top: 10px;
  border-radius: 11px;
  background: rgba(0, 0, 0, .2);
  border: 1px solid rgba(255, 255, 255, .045);
}
.segmented button {
  flex: 1;
  min-width: 0;
  padding: 7px 3px;
  border-radius: 8px;
  color: var(--muted-2);
  font-size: 10px;
  letter-spacing: .02em;
  white-space: nowrap;
  transition: .15s ease;
}
.segmented button:hover { color: var(--ink); }
.segmented button.is-active {
  color: #2e1c21;
  font-weight: 650;
  background: linear-gradient(150deg, #f0d4aa, #dca9a7);
  box-shadow: 0 2px 8px rgba(0, 0, 0, .22), inset 0 1px 0 rgba(255, 255, 255, .5);
}
.segmented.four button { font-size: 9.5px; }

.toggle {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 8px 12px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: rgba(255, 255, 255, .025);
  color: var(--muted);
  font-size: 10.5px;
  transition: .16s ease;
}
.toggle:hover { border-color: var(--line-strong); }
.toggle.wide { width: 100%; border-radius: 11px; margin-top: 7px; justify-content: flex-start; }
.toggle-dot {
  width: 16px;
  height: 16px;
  border-radius: 50%;
  border: 1px solid rgba(255, 255, 255, .22);
  background: rgba(0, 0, 0, .25);
  position: relative;
  transition: .16s ease;
}
.toggle-dot::after {
  content: '';
  position: absolute;
  inset: 4px;
  border-radius: 50%;
  background: transparent;
  transition: .16s ease;
}
.toggle.is-on { color: var(--ink); border-color: rgba(233, 195, 145, .36); background: rgba(233, 195, 145, .08); }
.toggle.is-on .toggle-dot { border-color: var(--gold); }
.toggle.is-on .toggle-dot::after { background: var(--gold); box-shadow: 0 0 7px rgba(233, 195, 145, .7); }
.toggle-row { display: flex; gap: 7px; flex-wrap: wrap; }

.sticker-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 7px; }
.sticker-btn {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 9px 8px;
  border-radius: 10px;
  border: 1px solid var(--line);
  background: rgba(255, 255, 255, .025);
  font-size: 10px;
  color: var(--muted);
  text-align: left;
  transition: .16s ease;
}
.sticker-btn span { font-size: 19px; line-height: 1; color: var(--gold); width: 18px; text-align: center; }
.sticker-btn:hover { border-color: var(--line-strong); background: rgba(255, 255, 255, .05); }
.sticker-btn.is-active { border-color: var(--gold); background: rgba(233, 195, 145, .1); color: var(--ink); box-shadow: 0 0 0 1px rgba(233, 195, 145, .22); }

.soft-btn {
  padding: 9px 12px;
  border-radius: 10px;
  border: 1px solid var(--line);
  background: rgba(255, 255, 255, .035);
  color: var(--muted);
  font-size: 10.5px;
  letter-spacing: .02em;
  transition: .16s ease;
}
.soft-btn:hover { color: var(--ink); border-color: var(--line-strong); background: rgba(255, 255, 255, .06); }
.soft-btn.danger:hover { color: #f2b2ad; border-color: rgba(242, 178, 173, .32); }
.button-row { display: flex; gap: 7px; flex-wrap: wrap; }

.tip-note {
  margin: 14px 0 0;
  padding: 9px 0 0 11px;
  border-left: 2px solid rgba(233, 195, 145, .45);
  font-size: 10.5px;
  line-height: 1.55;
  color: var(--muted-2);
}
.brush-note { margin: 0 0 11px; font-size: 11px; line-height: 1.55; color: var(--muted-2); }
.brush-preview-row { display: flex; align-items: center; gap: 10px; margin-top: 14px; color: var(--muted-2); font-size: 10px; }
.brush-preview {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  background: var(--brush, #c96f8c);
  box-shadow: inset 0 1px 2px rgba(255, 255, 255, .3), 0 0 0 4px rgba(255, 255, 255, .04);
  opacity: .9;
}

/* ---------- Start screen ---------- */
.screen {
  position: fixed;
  inset: 0;
  z-index: 100;
  display: grid;
  place-items: center;
  padding: 20px;
  overflow-y: auto;
  overscroll-behavior: contain;
}
.start-screen {
  background:
    radial-gradient(900px 680px at 50% 38%, rgba(96, 51, 79, .35), transparent 68%),
    linear-gradient(180deg, rgba(14, 8, 17, .76), rgba(13, 8, 16, .93));
  backdrop-filter: blur(14px) saturate(1.12);
}
.start-glow {
  position: fixed;
  width: 670px;
  height: 670px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(231, 160, 181, .18), transparent 66%);
  top: 50%;
  left: 50%;
  transform: translate(-50%, -58%);
  pointer-events: none;
  filter: blur(10px);
}
.start-inner { position: relative; width: min(920px, 100%); padding: 12px 0; }
.start-card { text-align: center; }
.start-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  font-size: 9px;
  letter-spacing: .34em;
  text-transform: uppercase;
  color: var(--gold);
  border: 1px solid rgba(233, 195, 145, .24);
  background: rgba(233, 195, 145, .06);
  border-radius: 999px;
  padding: 8px 15px;
}
.start-eyebrow span { font-size: 11px; }
.start-card h1 {
  margin: 22px 0 16px;
  font-family: var(--serif);
  font-weight: 400;
  font-size: clamp(52px, 8.4vw, 88px);
  line-height: .88;
  letter-spacing: -.025em;
}
.start-card h1 em {
  font-weight: 400;
  background: linear-gradient(100deg, #f7e4bf 6%, #eeb6b3 48%, #dd91a9 92%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  padding-right: .08em;
}
.start-lede {
  width: min(570px, 92%);
  margin: 0 auto;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.65;
  letter-spacing: .01em;
}
.mode-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; margin-top: 27px; text-align: left; }
.mode-card {
  position: relative;
  padding: 22px 22px 20px;
  border-radius: 20px;
  border: 1px solid var(--line);
  background: linear-gradient(150deg, rgba(63, 40, 63, .74), rgba(32, 21, 38, .82));
  transition: transform .22s ease, border-color .22s ease, box-shadow .22s ease;
  overflow: hidden;
}
.mode-card::before {
  content: '';
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: radial-gradient(300px 190px at 90% 0%, rgba(231, 160, 181, .17), transparent 70%);
}
.mode-card.free::before { background: radial-gradient(300px 190px at 90% 0%, rgba(158, 202, 172, .13), transparent 70%); }
.mode-card:hover { transform: translateY(-4px); border-color: rgba(233, 195, 145, .48); box-shadow: 0 22px 50px rgba(0, 0, 0, .34), 0 0 0 1px rgba(233, 195, 145, .12); }
.mode-badge {
  position: absolute;
  top: 16px;
  right: 16px;
  font-size: 8px;
  letter-spacing: .2em;
  color: var(--gold);
  border: 1px solid rgba(233, 195, 145, .26);
  border-radius: 999px;
  padding: 5px 8px;
}
.mode-icon { display: block; font-size: 28px; line-height: 1; color: var(--gold); margin-bottom: 15px; }
.mode-card.free .mode-icon { color: #b7d3bd; }
.mode-card h2 { margin: 0 0 8px; font-family: var(--serif); font-size: 25px; font-weight: 400; letter-spacing: .01em; }
.mode-card p { margin: 0 0 18px; font-size: 11.5px; line-height: 1.55; color: var(--muted); max-width: 330px; }
.mode-cta { display: inline-flex; align-items: center; gap: 7px; font-size: 10px; letter-spacing: .13em; text-transform: uppercase; color: var(--gold); font-weight: 600; }
.mode-cta b { font-size: 14px; transition: transform .18s ease; }
.mode-card:hover .mode-cta b { transform: translateX(4px); }
.start-note { margin-top: 22px; font-size: 9.5px; letter-spacing: .07em; color: var(--muted-2); display: flex; justify-content: center; gap: 8px; flex-wrap: wrap; }
.start-dot { opacity: .6; }

/* ---------- Modal / toast ---------- */
.modal-screen { background: rgba(12, 7, 15, .68); backdrop-filter: blur(9px); z-index: 120; }
.modal-card {
  width: min(520px, 100%);
  max-height: 88dvh;
  overflow-y: auto;
  padding: 30px 30px 26px;
  border-radius: 24px;
  border: 1px solid rgba(233, 195, 145, .26);
  background:
    radial-gradient(420px 240px at 50% -8%, rgba(231, 160, 181, .15), transparent 70%),
    linear-gradient(165deg, #342138, #211527 64%, #1c1220);
  box-shadow: 0 35px 100px rgba(0, 0, 0, .6), inset 0 1px 0 rgba(255, 255, 255, .09);
  position: relative;
  animation: modalIn .28s cubic-bezier(.2, .9, .25, 1.15);
}
@keyframes modalIn { from { opacity: 0; transform: translateY(16px) scale(.97); } to { opacity: 1; transform: none; } }
.modal-close {
  position: absolute;
  top: 14px;
  right: 14px;
  width: 32px;
  height: 32px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  border: 1px solid var(--line);
  color: var(--muted);
  font-size: 16px;
  line-height: 1;
}
.modal-close:hover { color: var(--ink); border-color: var(--line-strong); }
.modal-kicker { display: block; text-align: center; font-size: 8.5px; letter-spacing: .28em; color: var(--gold-deep); text-transform: uppercase; }
.modal-card h2 { margin: 9px 0 0; text-align: center; font-family: var(--serif); font-size: 31px; font-weight: 400; line-height: 1.05; }
.modal-lede { margin: 10px auto 0; text-align: center; font-size: 11.5px; line-height: 1.6; color: var(--muted); max-width: 380px; }
.stars-row { display: flex; justify-content: center; gap: 7px; margin: 20px 0 4px; }
.star { font-size: 42px; line-height: 1; color: rgba(255, 255, 255, .12); text-shadow: none; transition: .3s ease; }
.star.is-on { color: var(--gold); text-shadow: 0 0 18px rgba(233, 195, 145, .55); animation: starPop .45s cubic-bezier(.2, 1.6, .4, 1) both; }
.star:nth-child(2).is-on { animation-delay: .12s; }
.star:nth-child(3).is-on { animation-delay: .24s; }
@keyframes starPop { from { transform: scale(.4) rotate(-18deg); opacity: 0; } to { transform: scale(1) rotate(0); opacity: 1; } }
.score-big { text-align: center; font-family: var(--serif); font-size: 44px; color: var(--ink); line-height: 1; margin-top: 10px; }
.score-big small { font-family: var(--sans); font-size: 10px; letter-spacing: .18em; color: var(--muted-2); text-transform: uppercase; display: block; margin-top: 5px; }
.result-list { margin: 18px 0 2px; display: grid; gap: 7px; }
.result-row { display: flex; align-items: center; gap: 9px; padding: 9px 11px; border-radius: 10px; background: rgba(255, 255, 255, .035); border: 1px solid transparent; font-size: 11px; color: var(--muted); }
.result-row .r-icon { width: 18px; height: 18px; flex: 0 0 auto; display: grid; place-items: center; border-radius: 50%; font-size: 10px; background: rgba(255, 255, 255, .06); }
.result-row.is-ok { color: #ddf1dd; border-color: rgba(134, 201, 140, .2); background: rgba(89, 153, 97, .1); }
.result-row.is-ok .r-icon { color: #2c3d2d; background: #a9d9ac; }
.result-row.is-miss { color: var(--muted-2); }
.result-row.is-miss .r-icon { color: #e6b3ae; background: rgba(230, 179, 174, .12); }
.result-points { margin-left: auto; font-size: 10px; letter-spacing: .05em; color: var(--gold); }
.result-points.dim { color: var(--muted-2); }
.time-bonus { display: flex; justify-content: space-between; margin-top: 12px; padding: 10px 12px; border-radius: 10px; background: rgba(233, 195, 145, .07); border: 1px solid rgba(233, 195, 145, .14); font-size: 10.5px; color: var(--muted); }
.time-bonus strong { color: var(--gold); }
.modal-actions { display: flex; gap: 9px; justify-content: center; margin-top: 20px; flex-wrap: wrap; }
.modal-btn {
  min-width: 142px;
  padding: 12px 18px;
  border-radius: 11px;
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: .1em;
  text-transform: uppercase;
  transition: .16s ease;
}
.modal-btn.primary {
  color: #2a191f;
  background: linear-gradient(135deg, #f0d3a6, #e1aba8 55%, #ce879d);
  box-shadow: 0 8px 22px rgba(201, 111, 140, .22), inset 0 1px 0 rgba(255, 255, 255, .5);
}
.modal-btn.primary:hover { transform: translateY(-1px); filter: brightness(1.04); }
.modal-btn.ghost { color: var(--muted); border: 1px solid var(--line); background: rgba(255, 255, 255, .03); }
.modal-btn.ghost:hover { color: var(--ink); border-color: var(--line-strong); }

.help-steps { display: grid; gap: 13px; margin: 20px 0 0; }
.help-step { display: flex; gap: 12px; align-items: flex-start; }
.help-num { width: 25px; height: 25px; flex: 0 0 auto; display: grid; place-items: center; border-radius: 50%; border: 1px solid rgba(233, 195, 145, .3); color: var(--gold); font-family: var(--serif); font-size: 12px; }
.help-step h4 { margin: 2px 0 3px; font-size: 11.5px; font-weight: 600; letter-spacing: .03em; }
.help-step p { margin: 0; font-size: 10.5px; line-height: 1.55; color: var(--muted-2); }
.help-foot { margin-top: 22px; padding-top: 16px; border-top: 1px solid var(--line); font-size: 9.5px; line-height: 1.6; color: var(--muted-2); text-align: center; letter-spacing: .02em; }

.confetti { position: absolute; inset: 0; pointer-events: none; overflow: hidden; border-radius: 24px; }
.confetti i {
  position: absolute;
  top: -12px;
  width: 7px;
  height: 12px;
  border-radius: 2px;
  background: var(--gold);
  opacity: 0;
  animation: confettiFall 1.6s ease-in forwards;
}
@keyframes confettiFall {
  0% { opacity: 1; transform: translate3d(0, -20px, 0) rotate(0); }
  100% { opacity: 0; transform: translate3d(var(--dx), 480px, 0) rotate(var(--rot)); }
}

.toast {
  position: fixed;
  left: 50%;
  bottom: 28px;
  transform: translate(-50%, 12px);
  z-index: 200;
  max-width: calc(100% - 32px);
  padding: 10px 17px;
  border-radius: 999px;
  border: 1px solid rgba(233, 195, 145, .3);
  background: rgba(30, 18, 33, .94);
  box-shadow: 0 12px 36px rgba(0, 0, 0, .45);
  color: var(--ink);
  font-size: 11px;
  letter-spacing: .02em;
  white-space: nowrap;
  opacity: 0;
  pointer-events: none;
  transition: .25s ease;
  backdrop-filter: blur(12px);
}
.toast.show { opacity: 1; transform: translate(-50%, 0); }

/* ---------- Responsive ---------- */
@media (max-width: 980px) {
  .workspace {
    grid-template-columns: minmax(0, 1fr);
    grid-template-rows: minmax(0, 47dvh) minmax(0, 1fr);
    gap: 10px;
    padding: 10px 12px max(12px, env(safe-area-inset-bottom));
  }
  .topbar { height: 58px; padding: 0 14px; }
  .brand-mark { width: 35px; height: 35px; font-size: 19px; }
  .brand-text b { font-size: 16px; }
  .brand-text small { display: none; }
  .hud { display: none; }
  .stage-wrap { gap: 8px; }
  .stage-toolbar { padding: 5px; gap: 5px; }
  .tool-btn { height: 36px; padding: 0 9px; font-size: 10px; }
  .present-btn { height: 38px; padding: 0 14px; font-size: 11px; }
  .panel { border-radius: 20px; }
  .panel-top { padding: 11px 14px 9px; }
  .mode-row h2 { font-size: 21px; }
  .free-intro { margin-top: 8px; }
  .free-intro p { display: none; }
  .preset-row { margin-top: 7px; }
  .client-card { margin-top: 8px; padding: 9px 10px; }
  .avatar { width: 34px; height: 34px; font-size: 15px; }
  .client-id h3 { font-size: 15px; }
  .brief-text { margin: 6px 0 5px; font-size: 10.5px; line-height: 1.4; }
  .checklist { gap: 4px; }
  .check { font-size: 9px; padding: 3px 7px 3px 5px; }
  .tabs { padding: 5px 7px; }
  .tab { padding: 6px 2px 5px; font-size: 8.5px; gap: 3px; }
  .tab svg { width: 17px; height: 17px; }
  .panel-body { padding: 0 14px 20px; }
  .group { padding: 11px 0; }
  .swatch { width: 31px; height: 31px; }
  .skin-swatches .swatch { width: 34px; height: 34px; }
  .shadow-swatches .swatch, .lip-swatches .swatch { width: 28px; height: 28px; }
  .segmented { margin-top: 8px; }
  .segmented button { padding: 6px 2px; font-size: 9.5px; }
  .modal-card { padding: 25px 20px 22px; }
  .modal-card h2 { font-size: 27px; }
  .mode-grid { margin-top: 20px; }
  .mode-card { padding: 18px; }
  .mode-card h2 { font-size: 22px; }
  .start-card h1 { margin: 16px 0 13px; }
}

@media (max-width: 560px) {
  .tool-btn span { display: none; }
  .tool-btn { width: 36px; justify-content: center; padding: 0; }
  .present-btn { flex: 1; }
  .start-screen { padding: 14px; }
  .start-card h1 { font-size: clamp(44px, 14vw, 62px); }
  .start-lede { font-size: 12px; }
  .mode-grid { grid-template-columns: 1fr; gap: 10px; }
  .mode-card { padding: 15px 17px; }
  .mode-card p { margin-bottom: 12px; font-size: 11px; }
  .mode-icon { font-size: 22px; margin-bottom: 9px; }
  .mode-card h2 { font-size: 21px; margin-bottom: 5px; }
  .start-note span:last-child { display: none; }
  .start-dot { display: none; }
  .modal-actions { flex-direction: column; }
  .modal-btn { width: 100%; }
  .star { font-size: 36px; }
}

@media (max-width: 380px) {
  .workspace { padding-left: 8px; padding-right: 8px; }
  .tab span { display: none; }
  .tab { padding: 8px 2px; }
  .mode-row h2 { font-size: 19px; }
  .client-card { padding: 8px; }
}

@media (max-height: 720px) and (min-width: 981px) {
  .workspace { padding-top: 12px; padding-bottom: 12px; gap: 16px; }
  .panel-top { padding-top: 13px; }
  .group { padding: 10px 0; }
  .free-intro p { font-size: 10.5px; }
  .client-card { margin-top: 9px; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: .01ms !important; transition-duration: .01ms !important; }
}

