        lash.x + Math.cos(lash.a) * lash.l * .8,
        lash.y + Math.sin(lash.a) * lash.l * .8
      );
      ctx.stroke();
    }
    softEllipse(360, 468, 55, 9, '#2a1b1d', .13);
  }
}

